function check(input, actual, expected) {
  const [rowSum, colSum] = input;
  if (!Array.isArray(actual) || actual.length !== rowSum.length) return false;
  const columnTotals = new Array(colSum.length).fill(0);
  for (let i = 0; i < rowSum.length; i++) {
    const row = actual[i];
    if (!Array.isArray(row) || row.length !== colSum.length) return false;
    let rowTotal = 0;
    for (let j = 0; j < row.length; j++) {
      const value = row[j];
      if (!Number.isInteger(value) || value < 0) return false;
      rowTotal += value;
      columnTotals[j] += value;
    }
    if (rowTotal !== rowSum[i]) return false;
  }
  return columnTotals.every((total, j) => total === colSum[j]);
}

