  if (rowSum.some(v => v < 0 || v > 100000000) || colSum.some(v => v < 0 || v > 100000000)) return 'Every sum is between 0 and 10^8.';
  const total = (list) => list.reduce((a, b) => a + b, 0);
  if (total(rowSum) !== total(colSum)) return 'rowSum and colSum must have the same total.';
  return null;
