function restoreMatrix(rowSum, colSum) {
  const rowLeft = [...rowSum];
  const colLeft = [...colSum];
  const matrix = rowSum.map(() => new Array(colSum.length).fill(0));
  let i = 0;
  let j = 0;

  while (i < rowLeft.length && j < colLeft.length) {
    const value = Math.min(rowLeft[i], colLeft[j]);
    matrix[i][j] = value;
    rowLeft[i] -= value;
    colLeft[j] -= value;
    if (rowLeft[i] === 0) {
      i++;
    } else {
      j++;
    }
  }
  return matrix;
}

