function restoreMatrix(rowSum, colSum) {
  // The hint's method: repeatedly take the smallest open row or column total and settle it in one cell.
  const rows = rowSum.slice(), cols = colSum.slice();
  const out = rowSum.map(() => colSum.map(() => 0));
  const rowOpen = rows.map(() => true), colOpen = cols.map(() => true);
  for (;;) {
    let pick = null;
    for (let r = 0; r < rows.length; r++) if (rowOpen[r] && (pick === null || rows[r] < pick.amount)) pick = { isRow: true, at: r, amount: rows[r] };
    for (let c = 0; c < cols.length; c++) if (colOpen[c] && (pick === null || cols[c] < pick.amount)) pick = { isRow: false, at: c, amount: cols[c] };
    if (pick === null) break;
    if (pick.isRow) {
      const c = colOpen.indexOf(true);
      if (c >= 0) { out[pick.at][c] += pick.amount; cols[c] -= pick.amount; }
      rows[pick.at] = 0;
      rowOpen[pick.at] = false;
    } else {
      const r = rowOpen.indexOf(true);
      if (r >= 0) { out[r][pick.at] += pick.amount; rows[r] -= pick.amount; }
      cols[pick.at] = 0;
      colOpen[pick.at] = false;
    }
  }
  return out;
}

