function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  let rows, cols;
  if (size === 'large') {
    const shapes = [[100, 100], [100, 1], [1, 100], [100, 37], [64, 100]];
    [rows, cols] = shapes[int(0, shapes.length - 1)];
  } else {
    rows = int(1, 4);
    cols = int(1, 4);
  }
  // Hide a random matrix and publish its row and column totals, so a valid answer always exists.
  const limit = Math.floor(100000000 / Math.max(rows, cols));
  const cap = size === 'large' ? (rand() < 0.5 ? limit : 1000) : (rand() < 0.2 ? limit : 6);
  const zeroRate = rand() * 0.6;
  const rowSum = new Array(rows).fill(0), colSum = new Array(cols).fill(0);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const value = rand() < zeroRate ? 0 : int(0, cap);
      rowSum[r] += value;
      colSum[c] += value;
    }
  }
  return [rowSum, colSum];
}
